<?php
namespace InProsper\Repositories;
use InProsper\Core\Database;
use PDO;
final class OrderRepository {
    private PDO $db; public function __construct(){ $this->db=Database::connection(); }
    public function create(array $order,array $item,string $method,string $destination): int {
        $s=$this->db->prepare('INSERT INTO orders (consumer_id,order_date,status,total_amount,created_at) VALUES (?,NOW(),"menunggu_pembayaran",?,NOW())'); $s->execute([$order['consumer_id'],$order['total']]); $id=(int)$this->db->lastInsertId();
        $s=$this->db->prepare('INSERT INTO order_details (order_id,product_id,quantity,unit_price,subtotal) VALUES (?,?,?,?,?)'); $s->execute([$id,$item['product_id'],$item['quantity'],$item['unit_price'],$item['subtotal']]);
        $s=$this->db->prepare('INSERT INTO transactions (order_id,payment_reference,amount,payment_status,expires_at,created_at) VALUES (?, ?, ?, "menunggu", DATE_ADD(NOW(), INTERVAL 15 MINUTE), NOW())'); $s->execute([$id,'INP-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),$order['total']]);
        $s=$this->db->prepare('INSERT INTO deliveries (order_id,fulfillment_method,destination_address,delivery_status,created_at) VALUES (?,?,?,"belum_diproses",NOW())'); $s->execute([$id,$method,$destination]); return $id;
    }
    public function aggregate(int $id): ?array {
        $s=$this->db->prepare('SELECT o.*,u.name AS consumer_name,u.email AS consumer_email,t.payment_status,t.payment_reference,t.amount,t.expires_at,d.fulfillment_method,d.destination_address,d.delivery_status,m.user_id AS merchant_user_id,m.business_name FROM orders o JOIN users u ON u.user_id=o.consumer_id LEFT JOIN transactions t ON t.order_id=o.order_id LEFT JOIN deliveries d ON d.order_id=o.order_id JOIN order_details od ON od.order_id=o.order_id JOIN products p ON p.product_id=od.product_id JOIN merchants m ON m.merchant_id=p.merchant_id WHERE o.order_id=?'); $s->execute([$id]); $o=$s->fetch(); if(!$o)return null;
        $s=$this->db->prepare('SELECT od.*,p.name AS product_name,p.photo_url,p.merchant_id,p.stock FROM order_details od JOIN products p ON p.product_id=od.product_id WHERE od.order_id=?'); $s->execute([$id]); $o['items']=$s->fetchAll(); return $o;
    }
    public function expireStalePending(?int $consumerId=null): void { $sql='UPDATE orders o JOIN transactions t ON t.order_id=o.order_id SET o.status=\"dibatalkan\",t.payment_status=\"kedaluwarsa\" WHERE o.status=\"menunggu_pembayaran\" AND t.payment_status=\"menunggu\" AND t.expires_at<=NOW()'; $args=[]; if($consumerId!==null){$sql.=' AND o.consumer_id=?';$args[]=$consumerId;} $s=$this->db->prepare($sql);$s->execute($args); }
    public function forConsumer(int $userId): array { $this->expireStalePending($userId); $s=$this->db->prepare('SELECT o.*,t.payment_status,t.payment_reference,d.fulfillment_method,d.destination_address,d.delivery_status,(SELECT GROUP_CONCAT(p.name SEPARATOR ", ") FROM order_details od JOIN products p ON p.product_id=od.product_id WHERE od.order_id=o.order_id) AS product_names FROM orders o LEFT JOIN transactions t ON t.order_id=o.order_id LEFT JOIN deliveries d ON d.order_id=o.order_id WHERE o.consumer_id=? ORDER BY o.order_date DESC'); $s->execute([$userId]); return $s->fetchAll(); }
    public function forMerchant(int $merchantId): array { $this->expireStalePending(); $s=$this->db->prepare('SELECT DISTINCT o.*,u.name AS consumer_name,t.payment_status,t.payment_reference,d.fulfillment_method,d.destination_address,d.delivery_status,(SELECT GROUP_CONCAT(CONCAT(p2.name," ×",od2.quantity) SEPARATOR ", ") FROM order_details od2 JOIN products p2 ON p2.product_id=od2.product_id WHERE od2.order_id=o.order_id) AS product_names FROM orders o JOIN order_details od ON od.order_id=o.order_id JOIN products p ON p.product_id=od.product_id JOIN users u ON u.user_id=o.consumer_id LEFT JOIN transactions t ON t.order_id=o.order_id LEFT JOIN deliveries d ON d.order_id=o.order_id WHERE p.merchant_id=? ORDER BY o.order_date DESC'); $s->execute([$merchantId]); return $s->fetchAll(); }
    public function updatePayment(int $orderId,string $status): void { $s=$this->db->prepare('UPDATE transactions SET payment_status=?,paid_at=IF(?="berhasil",NOW(),paid_at) WHERE order_id=?'); $s->execute([$status,$status,$orderId]); }
    public function updateStatus(int $orderId,string $status): void { $s=$this->db->prepare('UPDATE orders SET status=? WHERE order_id=?'); $s->execute([$status,$orderId]); }
    public function updateDelivery(int $orderId,string $status,?string $reference=null): void { $s=$this->db->prepare('UPDATE deliveries SET delivery_status=?,courier_reference=COALESCE(?,courier_reference) WHERE order_id=?'); $s->execute([$status,$reference,$orderId]); }
    public function grossTransactions(): float { return (float)$this->db->query('SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status IN ("dibayar","diproses","selesai")')->fetchColumn(); }
    public function countSuccessful(): int { return (int)$this->db->query('SELECT COUNT(*) FROM orders WHERE status IN ("dibayar","diproses","selesai")')->fetchColumn(); }
}
